<?php session_start();?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lavash N1 • Kuryer Pro</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:linear-gradient(180deg,#fff7f1,#f6f7fb);color:#101828}.wrap{max-width:1100px;margin:auto;padding:18px}.hero{padding:24px;border-radius:26px;background:linear-gradient(135deg,#111827,#293548);color:#fff;box-shadow:0 25px 70px #10182822}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:14px 0}.card,.order{background:#fff;border:1px solid #e4e7ec;border-radius:20px;padding:17px;box-shadow:0 16px 45px #1018280d}.metric{font-size:25px;font-weight:1000;margin-top:4px}.order{margin:12px 0}.muted{color:#667085}.pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#dcfce7;font-weight:900;font-size:12px}.btn{display:inline-block;border:0;border-radius:13px;padding:11px 14px;margin:4px 4px 0 0;background:linear-gradient(135deg,#ff4d00,#ff8a00);color:#fff;text-decoration:none;font-weight:900;cursor:pointer}.dark{background:#111827}.map{margin-top:8px;border:1px solid #eaecf0;border-radius:14px;overflow:hidden}.map iframe{width:100%;height:190px;border:0;display:block}.history{max-height:520px;overflow:auto}.login{max-width:430px;margin:70px auto}.login input{width:100%;padding:12px;margin:7px 0;border:1px solid #d0d5dd;border-radius:13px;font:inherit}.login button{width:100%}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.wrap{padding:12px}.grid{grid-template-columns:1fr 1fr}.hero h1{font-size:23px}}
</style></head><body><div class="wrap"><div class="hero"><div style="font-size:38px">🛵</div><h1>Lavash N1 • Kuryer Pro</h1><p>Buyurtma, xarita, yo‘l va kunlik yetkazib berish statistikasi.</p></div><div id="app" style="margin-top:14px">Yuklanmoqda...</div></div><script>const api=(a,o={})=>fetch('courier_api.php?action='+a,o).then(r=>r.json()),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));let app=document.getElementById('app');function map(x){let lat=Number(x.lat),lng=Number(x.lng);if(!lat||!lng)return '';let q=encodeURIComponent(lat+','+lng);return '<div class="map"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><a class="btn dark" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Google Maps’da yo‘l</a>'}async function boot(){let m=await api('me');if(!m.ok){app.innerHTML='<div class="card login"><h2>🔐 Kuryer kirishi</h2><p class="muted">URL orqali kirish.</p><input id="login" placeholder="Login: Daler"><input id="pass" type="password" placeholder="Parol: Lavash"><button class="btn" onclick="goLogin()">Kirish</button><p id="err" style="color:#b42318"></p></div>';return}render(m.data)}async function goLogin(){let f=new FormData();f.append('login',document.getElementById('login').value);f.append('password',document.getElementById('pass').value);let d=await api('login',{method:'POST',body:f});d.ok?location.reload():document.getElementById('err').textContent=d.message||'Server xatosi'}async function render(me){let s=await api('summary');let h=await api('history');let o=await api('orders');let d=s.data||{};app.innerHTML='<div class="grid"><div class="card">👤<div class="metric">'+esc(me.name)+'</div><span class="pill">ONLINE</span></div><div class="card">📦 Faol<div class="metric">'+((o.data||[]).length)+'</div></div><div class="card">💰 Bugun<div class="metric">'+Number(d.sales||0).toLocaleString('uz-UZ')+' so‘m</div></div><div class="card">✅ Yetkazilgan<div class="metric">'+(d.completed||0)+'</div></div></div><div class="card"><button class="btn dark" onclick="logout()">Chiqish</button><h2>🛵 Faol buyurtmalar</h2><div id="active">'+((o.data||[]).map(x=>'<div class="order"><b>#'+x.id+' — '+esc(x.customer_name)+'</b><p>📞 '+esc(x.phone)+'<br>📍 '+esc(x.address||'')+'<br>💰 '+Number(x.amount).toLocaleString('uz-UZ')+' so‘m · '+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</p>'+map(x)+'<p class="muted">'+esc(x.note||'')+'</p><button class="btn" onclick="st('+x.id+',\'delivering\')">🛵 Yo‘lda</button><button class="btn" onclick="st('+x.id+',\'completed\')">✅ Yetkazildi</button></div>').join('')||'<p class="muted">Faol buyurtma yo‘q.</p>')+'</div></div><div class="card" style="margin-top:14px"><h2>🧾 Buyurtma tarixi</h2><div class="history">'+((h.data||[]).map(x=>'<div class="order"><b>#'+x.id+' '+esc(x.customer_name)+'</b><br><span class="muted">'+new Date(x.created_at).toLocaleString('uz-UZ')+' · '+esc(x.status)+'</span><br>'+Number(x.amount).toLocaleString('uz-UZ')+' so‘m · '+((x.payment_method||'cash')==='card'?'Karta':'Naqd')+'</div>').join('')||'<p class="muted">Tarix yo‘q.</p>')+'</div></div>'}async function st(id,s){let f=new FormData();f.append('order_id',id);f.append('status',s);await api('status',{method:'POST',body:f});render((await api('me')).data)}async function logout(){await api('logout');location.reload()}boot();setInterval(()=>api('me').then(m=>m.ok&&render(m.data)),10000);</script></body></html>